import{c as t,Q as a,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"BLIP-2: Bootstrapping Language-Image Pre-training with Frozen Image Encoders and Large Language Models","description":"","frontmatter":{"url":"https://arxiv.org/abs/2301.12597","title":"BLIP-2: Bootstrapping Language-Image Pre-training with Frozen Image Encoders and Large Language Models","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2301.12597,"authors":["Junnan Li","Dongxu Li","Silvio Savarese","Steven Hoi"],"pdf_path":"pdfs/2301.12597.pdf","published_date":"2023-01-01T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2023-01-30-blip2-language-image-pretraining-frozen-encoders-2301-12597.md","filePath":"research/papers/2023-01-30-blip2-language-image-pretraining-frozen-encoders-2301-12597.md","lastUpdated":1785909234000}'),i={name:"research/papers/2023-01-30-blip2-language-image-pretraining-frozen-encoders-2301-12597.md"};function o(s,e,g,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="blip-2-bootstrapping-language-image-pre-training-with-frozen-image-encoders-and-large-language-models" tabindex="-1">BLIP-2: Bootstrapping Language-Image Pre-training with Frozen Image Encoders and Large Language Models <a class="header-anchor" href="#blip-2-bootstrapping-language-image-pre-training-with-frozen-image-encoders-and-large-language-models" aria-label="Permalink to &quot;BLIP-2: Bootstrapping Language-Image Pre-training with Frozen Image Encoders and Large Language Models&quot;">​</a></h1><p><strong>Authors:</strong> Junnan Li, Dongxu Li, Silvio Savarese, Steven Hoi <strong>Year:</strong> 2023 <strong>Venue:</strong> ICML 2023 <strong>ArXiv:</strong> <a href="https://arxiv.org/abs/2301.12597" target="_blank" rel="noreferrer">https://arxiv.org/abs/2301.12597</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>The cost of vision-and-language pre-training has become increasingly prohibitive due to end-to-end training of large-scale models. To this end, we propose BLIP-2, a generic and efficient pre-training strategy that bootstraps vision-language pre-training from off-the-shelf frozen pre-trained image encoders and frozen large language models. BLIP-2 bridges the modality gap with a lightweight Querying Transformer, which is pre-trained in two stages. The first stage bootstraps vision-language representation learning from a frozen image encoder. The second stage bootstraps vision-to-language generative learning from a frozen language model. BLIP-2 achieves state-of-the-art performance on various vision-language tasks, despite having significantly fewer trainable parameters than existing methods. For example, our model outperforms Flamingo80B by 8.7% on zero-shot VQAv2 with 54x fewer trainable parameters. We also demonstrate the model&#39;s emerging capabilities of zero-shot image-to-text generation guided by a natural language instruction.</p><hr><h2 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h2><ul><li><strong>Q-Former (Querying Transformer)</strong>: a lightweight transformer with a fixed set of learnable query tokens that bridges a frozen vision encoder and a frozen LLM, extracting the most task-relevant visual features for language generation</li><li><strong>Two-stage pre-training</strong>: Stage 1 aligns Q-Former queries with a frozen vision encoder via image-text contrastive learning, image-grounded text generation, and image-text matching; Stage 2 connects Q-Former output to a frozen LLM via a linear projection for generative vision-language learning</li><li>Outperforms <strong>Flamingo80B by 8.7% on zero-shot VQAv2</strong> with <strong>54x fewer trainable parameters</strong> (~188M vs. ~10B trainable), demonstrating extreme parameter efficiency</li><li>Demonstrates <strong>emerging zero-shot image-to-text generation</strong> capabilities guided by natural language instructions, without explicit instruction-following training</li><li><strong>ICML 2023</strong> — Q-Former architecture established a highly influential connector paradigm adopted by InstructBLIP, MiniGPT-4, X-LLM, and many subsequent multimodal models</li><li>Shows that independently bootstrapping each modality bridge (vision→Q-Former, then Q-Former→LLM) is more sample-efficient than joint end-to-end training</li><li>Compatible with any combination of frozen vision encoder (ViT-L, ViT-g) and frozen LLM (OPT, FlanT5), making it a modular and future-proof architecture</li></ul><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>BLIP-2&#39;s central innovation is the Q-Former: a transformer module with N learnable query tokens (N=32) that interact with image features via cross-attention and with each other via self-attention. The query tokens serve as a compressed, task-oriented visual representation — they learn to extract the image information most relevant to language understanding. A key design choice is weight-sharing between the query self-attention and the text self-attention in the Q-Former, enabling the queries to condition on text context.</p><p><strong>Stage 1 — Representation Learning from Frozen Vision Encoder:</strong> The Q-Former is trained with three objectives simultaneously: (a) Image-Text Contrastive Learning (ITC) aligns query representations with text via contrastive loss across a batch; (b) Image-grounded Text Generation (ITG) trains queries to provide sufficient visual context for the Q-Former&#39;s transformer decoder to generate the paired text; (c) Image-Text Matching (ITM) trains a binary classifier on query outputs to distinguish matched vs. unmatched image-text pairs. The vision encoder (ViT-L/14 or ViT-g/14) is frozen throughout.</p><p><strong>Stage 2 — Generative Learning from Frozen LLM:</strong> The 32 output query tokens from Stage 1 are linearly projected to match the LLM&#39;s embedding dimension and prepended to the text input embeddings. For decoder-only LLMs (OPT family), a language modeling loss is used; for encoder-decoder LLMs (FlanT5 family), a prefix language modeling loss is applied. Only the linear projection and Q-Former parameters are updated; the LLM remains entirely frozen. This stage effectively teaches the LLM to interpret compressed visual tokens as a soft visual prefix.</p><hr><h2 id="main-results" tabindex="-1">Main Results <a class="header-anchor" href="#main-results" aria-label="Permalink to &quot;Main Results&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Benchmark</th><th>BLIP-2</th><th>Flamingo80B</th><th>Improvement</th></tr></thead><tbody><tr><td>Zero-shot VQAv2</td><td>65.0%</td><td>56.3%</td><td>+8.7%</td></tr><tr><td>Zero-shot NoCaps</td><td>121.6 CIDEr</td><td>—</td><td>SOTA</td></tr><tr><td>Zero-shot COCO Cap.</td><td>145.8 CIDEr</td><td>138.1</td><td>+7.7</td></tr><tr><td>Trainable params</td><td>~188M</td><td>~10B</td><td>54x fewer</td></tr></tbody></table><p>BLIP-2 achieves SOTA on zero-shot VQA, image captioning (NoCaps, COCO), and visual reasoning benchmarks while training only a small fraction of its total parameter count.</p><hr><h2 id="limitations-future-work" tabindex="-1">Limitations &amp; Future Work <a class="header-anchor" href="#limitations-future-work" aria-label="Permalink to &quot;Limitations &amp; Future Work&quot;">​</a></h2><ul><li>Q-Former&#39;s 32 query tokens may be insufficient for tasks requiring fine-grained spatial reasoning or dense prediction (detection, segmentation)</li><li>The two-stage training is sequential and decoupled; misalignment between what Stage 1 learns and what the LLM needs in Stage 2 can limit performance</li><li>Both vision encoder and LLM are frozen, preventing deep cross-modal representation learning — the model can only adapt visual features at the Q-Former level</li><li>Zero-shot instruction following is emergent but unreliable compared to explicitly instruction-tuned models (InstructBLIP addresses this)</li><li>Hallucination in generated text remains a concern when visual evidence is weak or ambiguous</li></ul><hr><h2 id="why-this-matters-for-ai-practitioners" tabindex="-1">Why This Matters for AI Practitioners <a class="header-anchor" href="#why-this-matters-for-ai-practitioners" aria-label="Permalink to &quot;Why This Matters for AI Practitioners&quot;">​</a></h2><p>BLIP-2 solved a critical practical problem: <strong>how to add vision to an existing LLM at minimal cost</strong>. By freezing both the vision encoder and LLM and only training the Q-Former bridge (~188M parameters), practitioners can build capable multimodal systems without GPU clusters for end-to-end pre-training.</p><p>The modular design is particularly valuable: as better vision encoders (e.g., EVA-CLIP) or better LLMs (e.g., LLaMA-2, Mistral) become available, they can be swapped in with only the lightweight Q-Former needing retraining. This future-proofing, combined with strong zero-shot performance, made BLIP-2 a foundational architecture for the open-source multimodal ecosystem and directly spawned InstructBLIP (instruction-tuned variant), MiniGPT-4 (fine-tuned on curated conversations), and numerous domain-specific adaptations.</p>',24)])])}const c=t(i,[["render",o]]);export{u as __pageData,c as default};
